INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',438,'{"_type":"chat:Message","id":"8641420749:680","threadId":"telegram:8641420749","text":"- a propos des ETF de Lola cest sur ses comptes Mediolanum en Espagne, mais elle est domiciliée fiscale au Portugal. Je n’ai pas les chiffres que tu me demandes sous la main mais je te les donnerai plus tard, on continue sans pour l’instant. \n- oui j’en ai bénéficié pour la premiere fois pour l’IRS 2025, je t’envoie le justificatif IRS dans le prochain message.","formatted":{"type":"root","children":[{"type":"list","ordered":false,"start":null,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"a propos des ETF de Lola cest sur ses comptes Mediolanum en Espagne, mais elle est domiciliée fiscale au Portugal. Je n’ai pas les chiffres que tu me demandes sous la main mais je te les donnerai plus tard, on continue sans pour l’instant.","position":{"start":{"line":1,"column":3,"offset":2},"end":{"line":1,"column":242,"offset":241}}}],"position":{"start":{"line":1,"column":3,"offset":2},"end":{"line":1,"column":243,"offset":242}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":243,"offset":242}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"oui j’en ai bénéficié pour la premiere fois pour l’IRS 2025, je t’envoie le justificatif IRS dans le prochain message.","position":{"start":{"line":2,"column":3,"offset":245},"end":{"line":2,"column":121,"offset":363}}}],"position":{"start":{"line":2,"column":3,"offset":245},"end":{"line":2,"column":121,"offset":363}}}],"position":{"start":{"line":2,"column":1,"offset":243},"end":{"line":2,"column":121,"offset":363}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":121,"offset":363}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"c